/* Analytics belongs to Channel. No global navigation wrapper or background polling. */
(()=>{
 'use strict';
 const root=document.querySelector('#channel-dashboard');if(!root)return;
 const box=document.createElement('section');box.className='channel-analytics';box.setAttribute('aria-label','Desempenho do canal por período');
 box.innerHTML=`<div class="ca-heading"><div><p class="eyebrow">ANALYTICS · ALÉM DOS TOTAIS</p><h2>O tempo que seu conteúdo conquista.</h2></div><div class="ca-periods" role="group" aria-label="Período do Analytics">${[7,28,90,365].map(d=>`<button data-ca-days="${d}" aria-pressed="${d===28}">${d===365?'1 ano':d+' dias'}</button>`).join('')}</div></div>
 <div class="ca-tabs" role="tablist" aria-label="Painéis do Analytics">${[['overview','Visão geral'],['videos','Conteúdo'],['audience','Audiência'],['tools','Ferramentas']].map(([id,title],i)=>`<button id="ca-tab-${id}" role="tab" aria-selected="${!i}" aria-controls="ca-panel-${id}" tabindex="${i?-1:0}" data-ca-tab="${id}">${title}</button>`).join('')}</div>
 <p id="ca-status" role="status">Selecione um canal conectado para consultar seu Analytics.</p>
 <div id="ca-permission" hidden><strong>Uma autorização para ir mais longe.</strong><p>Horas assistidas e audiência são dados privados. O Google exige uma autorização de leitura específica, feita no navegador do Mac. O login por código da TV continua funcionando para suas contas.</p><button id="ca-authorize">Liberar Analytics</button><span id="ca-setup-note"></span></div>
 <div id="ca-panel-overview" role="tabpanel" aria-labelledby="ca-tab-overview">
 <div class="ca-visual"><article class="ca-watch" tabindex="0"><span class="ca-number">01 / ATENÇÃO</span><span>Tempo de exibição</span><strong id="ca-hours">—</strong><small>horas assistidas no período</small><p id="ca-period-label">Aguardando autorização</p></article><article class="ca-chart-card"><div class="ca-chart-head"><div><span class="ca-number">EVOLUÇÃO DIÁRIA</span><h3>Seu público, dia após dia.</h3></div><div class="ca-metrics" role="group" aria-label="Métrica diária"><button data-ca-metric="estimatedMinutesWatched" aria-pressed="true">Horas</button><button data-ca-metric="views" aria-pressed="false">Visualizações</button><button data-ca-metric="subscribersGained" aria-pressed="false">Inscritos ganhos</button></div></div><div id="ca-chart" tabindex="0"></div><div class="ca-axis"><span id="ca-axis-start">—</span><span id="ca-axis-end">—</span></div><p id="ca-chart-note">O gráfico aparecerá quando o YouTube retornar dados diários.</p></article></div>
 <div class="ca-kpis">${[['views','Visualizações','Neste período'],['duration','Duração média','Por visualização · min:seg'],['percentage','Percentual médio assistido','Média informada pelo YouTube'],['net','Saldo de inscritos','Ganhos menos perdas']].map(([id,title,note])=>`<article tabindex="0"><span>${title}</span><strong id="ca-${id}">—</strong><small>${note}</small></article>`).join('')}</div>
 <div class="ca-engagement" tabindex="0"><span>02 / CONVERSAS</span><p><strong id="ca-likes">—</strong> curtidas</p><p><strong id="ca-comments">—</strong> comentários</p><p><strong id="ca-shares">—</strong> compartilhamentos</p><p id="ca-subs-detail">Ganhos e perdas de inscritos ainda não disponíveis.</p></div></div>
 <div id="ca-panel-videos" role="tabpanel" aria-labelledby="ca-tab-videos" hidden><h3>Conteúdo que gera tempo de exibição.</h3><p>Até 10 vídeos, ordenados pelas horas assistidas neste período. Inclui vídeos além dos últimos envios.</p><div id="ca-top-videos">Aguardando autorização do Analytics.</div></div>
 <div id="ca-panel-audience" role="tabpanel" aria-labelledby="ca-tab-audience" hidden><div class="ca-audience-grid">${[['traffic','De onde chegam','insightTrafficSourceType'],['devices','Onde assistem','deviceType'],['countries','Países do público','country']].map(([id,title])=>`<article tabindex="0"><span class="ca-number">AUDIÊNCIA / ${title.toLocaleUpperCase('pt-BR')}</span><h3>${title}</h3><div id="ca-${id}">Sem relatório disponível.</div></article>`).join('')}</div><p>Percentuais calculados sobre as visualizações retornadas em cada relatório. O YouTube pode omitir grupos por privacidade; não equivalem a pessoas únicas.</p></div>
 <div id="ca-panel-tools" role="tabpanel" aria-labelledby="ca-tab-tools" hidden><div class="ca-tools"><article><h3>Seu espaço de trabalho.</h3><p>Abra o canal e acompanhe os dados detalhados no YouTube Studio.</p><a id="ca-studio" href="https://studio.youtube.com/" target="_blank" rel="noopener noreferrer">Abrir YouTube Studio ↗</a><button id="ca-export" disabled>Exportar evolução em CSV</button></article><article tabindex="0"><h3>O que estes dados significam?</h3><p>Tempo de exibição inclui os minutos retornados pelo Analytics; não representa as horas públicas elegíveis para monetização. Percentual médio assistido não é uma curva de retenção por segundo. Alcance único, impressões e CTR não são inferidos de visualizações.</p><p>Receita exige canal monetizado e uma autorização financeira separada. Nenhuma permissão financeira é solicitada aqui.</p></article></div></div>
 <footer class="ca-footer"><p id="ca-source">Fonte: YouTube Analytics API · atualização sob demanda, com cache de 15 minutos.</p><button id="ca-refresh">Atualizar Analytics ↻</button></footer>`;
 root.querySelector('#channel-stats-status').after(box);
 const $=id=>box.querySelector('#'+id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const finite=v=>typeof v==='number'&&Number.isFinite(v),fmt=(v,d=0)=>finite(v)?v.toLocaleString('pt-BR',{maximumFractionDigits:d}):'—',date=d=>/^\d{4}-\d{2}-\d{2}$/.test(d||'')?new Date(d+'T12:00:00Z').toLocaleDateString('pt-BR'):'—';
 let channel='',status={},days=28,metric='estimatedMinutesWatched',data=null,generation=0,busy=false,visible=!root.hidden;
 const memory=new Map();
 function selectTab(id,focus=false){for(const b of box.querySelectorAll('[data-ca-tab]')){const selected=b.dataset.caTab===id;b.setAttribute('aria-selected',String(selected));b.tabIndex=selected?0:-1;$('ca-panel-'+b.dataset.caTab).hidden=!selected;if(selected&&focus)b.focus()}}
 for(const b of box.querySelectorAll('[data-ca-tab]')){b.onclick=()=>selectTab(b.dataset.caTab);b.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();e.stopPropagation();const tabs=[...box.querySelectorAll('[data-ca-tab]')],i=tabs.indexOf(b),next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowLeft'?-1:1)+tabs.length)%tabs.length;selectTab(tabs[next].dataset.caTab,true)}}
 function clear(){data=null;for(const id of ['hours','views','duration','percentage','net','likes','comments','shares'])$('ca-'+id).textContent='—';$('ca-period-label').textContent='Sem dados neste período';$('ca-subs-detail').textContent='Ganhos e perdas de inscritos ainda não disponíveis.';$('ca-chart').replaceChildren();$('ca-chart-note').textContent='Sem dados diários disponíveis.';$('ca-axis-start').textContent='—';$('ca-axis-end').textContent='—';for(const id of ['traffic','devices','countries'])$('ca-'+id).textContent='Sem relatório disponível.';$('ca-top-videos').textContent='Sem relatório disponível.';$('ca-export').disabled=true;$('ca-source').textContent='Fonte: YouTube Analytics API · nenhum relatório carregado.'}
 function chart(){const daily=(data?.daily||[]).filter(r=>finite(r[metric])&&/^\d{4}-\d{2}-\d{2}$/.test(r.day)),divisor=metric==='estimatedMinutesWatched'?60:1,label={estimatedMinutesWatched:'horas assistidas',views:'visualizações',subscribersGained:'inscritos ganhos'}[metric];
  for(const b of box.querySelectorAll('[data-ca-metric]'))b.setAttribute('aria-pressed',String(b.dataset.caMetric===metric));
  if(!daily.length){$('ca-chart').textContent='Sem amostras para esta métrica.';$('ca-axis-start').textContent='—';$('ca-axis-end').textContent='—';$('ca-chart-note').textContent='O YouTube não retornou dados diários para esta métrica.';return}
  const start=Date.parse(data.startDate),span=Math.max(86400000,Date.parse(data.endDate)-start),max=Math.max(0,...daily.map(r=>r[metric]/divisor)),scale=Math.max(1,max),width=Math.max(2,Math.min(34,560/data.days*.7));
  const bars=daily.map(r=>{const h=r[metric]/divisor/scale*136,x=30+(Date.parse(r.day)-start)/span*540;return `<rect x="${x-width/2}" y="${156-h}" width="${width}" height="${h}" rx="1"><title>${esc(date(r.day))}: ${fmt(r[metric]/divisor,1)} ${label}</title></rect>`}).join('');
  $('ca-chart').innerHTML=`<svg viewBox="0 0 600 180" role="img" aria-label="${esc(label)} por dia. ${daily.length} dias retornados; máximo ${fmt(max,1)}. Datas sem dados ficam sem barras."><path d="M16 20H586M16 88H586M16 156H586" class="ca-grid"/>${bars}<text x="16" y="14">${fmt(max,1)} ${label}</text></svg>`;
  $('ca-axis-start').textContent=date(data.startDate);$('ca-axis-end').textContent=date(data.endDate);$('ca-chart-note').textContent=`${daily.length} dias com dados retornados · até ${date(data.availableThrough)}. Espaços sem amostra não são estimados.`;
 }
 const labels={YT_SEARCH:'Busca no YouTube',RELATED_VIDEO:'Vídeos sugeridos',SUBSCRIBER:'Recursos de navegação',EXT_URL:'Sites e apps externos',YT_CHANNEL:'Páginas de canais',PLAYLIST:'Playlists',NO_LINK_OTHER:'Direto ou desconhecido',SHORTS:'Feed de Shorts',NOTIFICATION:'Notificações',TV:'TV',MOBILE:'Celular',DESKTOP:'Computador',TABLET:'Tablet',GAME_CONSOLE:'Console',UNKNOWN_PLATFORM:'Plataforma desconhecida'};
 function breakdown(name,key){const rows=(data[name]||[]).filter(r=>finite(r.views)),sum=rows.reduce((s,r)=>s+r.views,0);let regions;try{regions=new Intl.DisplayNames(['pt-BR'],{type:'region'})}catch{}
  $('ca-'+name).innerHTML=rows.length?rows.slice(0,10).map(r=>{const raw=String(r[key]||'Não informado');let name=labels[raw]||raw;if(key==='country'&&/^[A-Z]{2}$/.test(raw))try{name=regions?.of(raw)||raw}catch{}const pct=sum?r.views/sum*100:0;return `<div class="ca-breakdown"><span>${esc(name)}</span><strong>${fmt(r.views)} <small>· ${fmt(pct,1)}%</small></strong><i><b style="width:${pct}%"></b></i></div>`}).join(''):'O YouTube não retornou grupos neste período.';
  if(data.errors?.[name])$('ca-'+name).textContent=data.errors[name];
 }
 function paint(result){data=result;const t=result.totals||{};$('ca-hours').textContent=fmt(t.watchHours,1);$('ca-views').textContent=fmt(t.views);$('ca-duration').textContent=finite(t.averageViewDuration)?Math.floor(Math.round(t.averageViewDuration)/60)+':'+String(Math.round(t.averageViewDuration)%60).padStart(2,'0'):'—';$('ca-percentage').textContent=finite(t.averageViewPercentage)?fmt(t.averageViewPercentage,1)+'%':'—';$('ca-net').textContent=finite(t.netSubscribers)?(t.netSubscribers>0?'+':'')+fmt(t.netSubscribers):'—';for(const key of ['likes','comments','shares'])$('ca-'+key).textContent=fmt(t[key]);$('ca-period-label').textContent=date(result.startDate)+' — '+date(result.endDate);$('ca-subs-detail').textContent=`Inscritos: ${fmt(t.subscribersGained)} ganhos · ${fmt(t.subscribersLost)} perdidos.`;chart();
  $('ca-status').textContent=(Object.keys(t).some(k=>finite(t[k]))?'Relatório carregado':'Nenhum dado retornado')+` · período de ${days} dias · dados diários até ${date(result.availableThrough)}. Pode haver atraso e revisões no YouTube.`;
  $('ca-source').textContent=`${result.cached?'Cache · ':''}${result.source} · consultado em ${new Date(result.at*1000).toLocaleString('pt-BR')} · cache de 15 min; atualização manual a cada 60 s.`+(result.refreshLimited?' Aguarde o intervalo mínimo para uma nova consulta.':'');
  const top=(result.topVideos||[]).filter(r=>/^[\w-]{11}$/.test(r.video));$('ca-top-videos').innerHTML=top.length?top.map((r,i)=>`<a class="ca-video" href="https://www.youtube.com/watch?v=${r.video}" target="_blank" rel="noopener noreferrer"><span class="ca-number">${String(i+1).padStart(2,'0')}</span><img loading="lazy" alt="" src="https://i.ytimg.com/vi/${r.video}/mqdefault.jpg"><span><strong>${esc(r.title||r.video)}</strong><small>${fmt(r.views)} visualizações · ${fmt(r.averageViewPercentage,1)}% assistido em média</small></span><b>${fmt(finite(r.estimatedMinutesWatched)?r.estimatedMinutesWatched/60:null,1)} h</b></a>`).join(''):'Nenhum vídeo retornado para o período.';if(result.errors?.topVideos)$('ca-top-videos').textContent=result.errors.topVideos;
  breakdown('traffic','insightTrafficSourceType');breakdown('devices','deviceType');breakdown('countries','country');$('ca-studio').href='https://studio.youtube.com/channel/'+encodeURIComponent(channel)+'/analytics';$('ca-export').disabled=!(result.daily||[]).length;
 }
 async function load(force=false){if(!visible||busy)return;if(!channel){$('ca-permission').hidden=true;$('ca-status').textContent='Selecione um canal conectado para consultar seu Analytics.';return}const account=(status.accounts||[]).find(a=>a.id===channel);$('ca-permission').hidden=false;
  if(!account){$('ca-status').textContent='Analytics disponível somente para um dos seus canais conectados. Canais públicos mantêm as estatísticas abaixo.';return}
  if(!status.analyticsVersion){$('ca-status').textContent='Atualize o serviço no Mac para ativar o novo painel Analytics. Os dados públicos continuam disponíveis abaixo.';return}
  $('ca-setup-note').textContent=status.configured?'Autorize o mesmo canal selecionado.':'Requer um cliente OAuth do tipo Aplicativo para computador no Mac.';
  if(!account.analytics){$('ca-status').textContent='Sua conta está conectada. Falta apenas a autorização específica do Analytics.';return}
  $('ca-permission').hidden=true;const key=channel+':'+days,cached=memory.get(key);if(!force&&cached&&Date.now()-cached.savedAt<900000){paint(cached.result);return}
  const rev=++generation,cid=channel,period=days;busy=true;$('ca-refresh').disabled=true;$('ca-status').textContent='Consultando o Analytics deste canal…';
  try{const result=await localJSON('/api/youtube/analytics?channel='+encodeURIComponent(cid)+'&days='+period+(force?'&force=1':''),60000);if(rev!==generation||cid!==channel||period!==days)return;if(result.channel!==cid||!result.totals||!Array.isArray(result.daily))throw Error('O serviço não retornou um relatório Analytics válido.');memory.set(key,{savedAt:Date.now(),result});while(memory.size>8)memory.delete(memory.keys().next().value);paint(result)}
  catch(e){if(rev===generation)$('ca-status').textContent=(data?'Mantendo a última consulta deste período. ':'')+e.message}
  finally{busy=false;$('ca-refresh').disabled=false;if(rev!==generation&&visible)load()}
 }
 document.addEventListener('peep-channel-visible',e=>{visible=e.detail.visible;if(!visible){generation++;return}});
 document.addEventListener('peep-channel-data',e=>{const next=e.detail.id;status=e.detail.status||{};if(next!==channel||!(status.accounts||[]).find(a=>a.id===next)?.analytics){channel=next;generation++;clear()}load()});
 for(const b of box.querySelectorAll('[data-ca-days]'))b.onclick=()=>{if(Number(b.dataset.caDays)===days)return;days=Number(b.dataset.caDays);generation++;for(const button of box.querySelectorAll('[data-ca-days]'))button.setAttribute('aria-pressed',String(Number(button.dataset.caDays)===days));clear();load()};
 for(const b of box.querySelectorAll('[data-ca-metric]'))b.onclick=()=>{metric=b.dataset.caMetric;if(data)chart()};
 $('ca-refresh').onclick=async()=>{try{status=await localJSON('/api/youtube/status');load(true)}catch(e){$('ca-status').textContent=e.message}};
 $('ca-authorize').onclick=()=>{if(!status.configured){show(`<p class="eyebrow">LEITURA DO ANALYTICS</p><h2>Configure a autorização no Mac.</h2><p>No mesmo projeto Google Cloud, habilite YouTube Analytics API. Em Clientes, crie um cliente OAuth do tipo Aplicativo para computador e baixe o JSON.</p><p>Execute <code>python3 android/autorizar_analytics.py --credenciais</code> seguido do arquivo JSON arrastado para o Terminal. O arquivo fica privado no Mac. O login e os canais da TV são preservados.</p><p>Você poderá autorizar cada canal separadamente. O Analytics pede somente leitura, sem acesso financeiro.</p>`);return}if(typeof PeepTV==='undefined'){window.open('/api/youtube/connect?analytics=1&channel='+encodeURIComponent(channel),'_blank','noopener,noreferrer');return}show(`<p class="eyebrow">YOUTUBE ANALYTICS</p><h2>Autorize pelo Mac.</h2><p>No Terminal do Mac, execute o comando abaixo. O navegador abrirá o Google para você escolher o canal e permitir a leitura dos relatórios.</p><pre>python3 android/autorizar_analytics.py</pre><p>Execute na pasta konka-glass. Selecione o mesmo canal da TV. Depois, volte aqui e pressione “Atualizar Analytics”. O login por QR da TV não oferece esta permissão.</p>`)};
 $('ca-export').onclick=()=>{if(!data?.daily?.length)return;if(typeof PeepTV!=='undefined'&&!new URLSearchParams(location.search).has('demo')){notify('Abra a guia Canal no navegador do Mac para baixar o CSV.');return}const keys=['day',...['views','estimatedMinutesWatched','averageViewDuration','averageViewPercentage','subscribersGained','subscribersLost','likes','comments','shares']],csv=keys.join(',')+'\r\n'+data.daily.map(r=>keys.map(k=>k==='day'?String(r[k]||'').replace(/[^\d-]/g,''):finite(r[k])?r[k]:'').join(',')).join('\r\n'),url=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download='youtube-analytics-'+data.startDate+'.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
})();
